#!/usr/bin/env python3
# NISCAYA MAKASSAR patch 0035: tema warna merah-putih (referensi Pinterest pin 293296994506469195).
# Hanya CSS tampilan; data & fungsi tidak disentuh. Idempoten: blok <style id="nm-tema-merah"> disisipkan
# sebelum </body> (setelah tema-2026 sehingga menimpanya), atau diganti bila versinya berbeda.
import sys, json, re
path = sys.argv[1]
CSS = json.loads('"/*TEMA-MERAH v1*/\\n/* Tema merah-putih gaya \\"Adlytics\\" (referensi Pinterest pin 293296994506469195).\\n   Hanya warna & tampilan — data, menu, tombol dan fungsi tidak diubah. Menimpa tema-2026 (biru). */\\n:root{\\n  --board-bg:#E3141B; --board-bg2:#B80F15;\\n  --bg:#F4F4F6; --surface:#FFFFFF; --surface-2:#F6F6F8; --border:#ECECEF;\\n  --text:#111114; --text-dim:#6B6B76; --text-faint:#9C9CA7;\\n  --accent:#E3141B; --accent-dim:#B80F15;\\n  --ready:#16A34A; --ready-dark:#15803D; --booking:#F59E0B; --sold:#B4B4BE; --danger:#E3141B;\\n  --yellow:#E3141B; --yellow-2:#FDECEC; --navy:#111114;\\n  --radius:14px;\\n  --display:\'Inter\',\'Plus Jakarta Sans\',sans-serif; --body:\'Inter\',\'Plus Jakarta Sans\',sans-serif;\\n  --shadow:0 1px 2px rgba(17,17,20,.04), 0 4px 16px rgba(17,17,20,.05);\\n  --nm-red:#E3141B; --nm-red-2:#B80F15; --nm-tint:#FDECEC; --nm-tint-2:#FFF5F5;\\n}\\nhtml{ background:#F4F4F6 !important; background-image:none !important; }\\nbody{ background:transparent; color:var(--text); }\\n::-webkit-scrollbar-thumb{ background:#D6D6DC; }\\n::selection{ background:#E3141B; color:#fff; }\\n\\n/* Sidebar putih bersih, menu aktif = pil merah */\\n#sidebar{ background:#fff !important; backdrop-filter:none !important; -webkit-backdrop-filter:none !important;\\n  border:1px solid #ECECEF !important; box-shadow:var(--shadow) !important; border-radius:18px; }\\n#sidebar .brand{ border-bottom:1px solid #F0F0F2; }\\n#sidebar .brand .brand-logo{ box-shadow:0 4px 14px rgba(227,20,27,.18); }\\n#sidebar .brand p{ color:var(--text-faint); }\\nnav button{ color:#55555F; font-weight:500; border-radius:10px; }\\nnav button .ic{ background:transparent !important; color:#8A8A95 !important; box-shadow:none !important; border-radius:8px; }\\nnav button:hover{ background:#F6F6F8 !important; color:var(--text); }\\nnav button:hover .ic{ color:var(--text) !important; }\\nnav button.active{ background:#E3141B !important; color:#fff !important; box-shadow:0 6px 16px rgba(227,20,27,.28) !important; font-weight:600; }\\nnav button.active .ic{ background:rgba(255,255,255,.18) !important; color:#fff !important; }\\n#sidebar .foot{ border-top:1px solid #F0F0F2; color:var(--text-faint); }\\n#sidebar .foot::before{ content:\'\'; display:block; height:3px; width:36px; border-radius:3px; margin-bottom:8px;\\n  background:linear-gradient(90deg,#E3141B,#FF6B6F); }\\n\\n/* Header */\\n#topbar{ background:rgba(255,255,255,.97) !important; border:1px solid #ECECEF !important; border-radius:16px;\\n  box-shadow:var(--shadow) !important; backdrop-filter:none !important; -webkit-backdrop-filter:none !important; }\\n#topbar::before{ background:#F4F4F6 !important; backdrop-filter:none !important; -webkit-backdrop-filter:none !important; }\\n#topbar h2{ color:var(--text); font-weight:700; letter-spacing:-.3px; }\\n#topbar .sub{ color:var(--text-faint); }\\n\\n/* Tombol */\\n.btn{ border-radius:10px; border:1px solid #E4E4E9; box-shadow:none; color:var(--text); }\\n.btn:hover{ background:#F6F6F8; }\\n.btn-primary{ background:#E3141B !important; border-color:#E3141B !important; color:#fff !important; box-shadow:0 4px 12px rgba(227,20,27,.25) !important; }\\n.btn-primary:hover{ background:#C81016 !important; }\\n.btn-ghost{ background:#fff; }\\n.btn-danger{ background:#fff; color:#E3141B; border-color:#F6C4C6; }\\n.icon-btn:hover{ background:#F6F6F8; }\\n\\n/* Kartu statistik: putih, label tebal hitam, keterangan abu */\\n.stat-card{ background:#fff !important; border:1px solid #ECECEF !important; border-radius:16px; box-shadow:var(--shadow) !important; }\\n.stat-card .lbl{ color:var(--text) !important; font-weight:600; }\\n.stat-card .val{ color:var(--text); font-weight:700; }\\n.stat-card .sub{ color:var(--text-faint) !important; }\\n.stat-card::after{ display:none !important; }\\n.grid-stats > .stat-card:nth-child(3){ background:linear-gradient(150deg,#F0262D 0%,#E3141B 45%,#A50D12 100%) !important; border-color:transparent !important;\\n  box-shadow:0 10px 24px rgba(227,20,27,.28) !important; }\\n.grid-stats > .stat-card:nth-child(3) .lbl, .grid-stats > .stat-card:nth-child(3) .val, .grid-stats > .stat-card:nth-child(3) .sub{ color:#fff !important; }\\n.grid-stats > .stat-card:nth-child(4){ background:#fff !important; border:1px solid #F6C4C6 !important; }\\n.grid-stats > .stat-card:nth-child(4) .lbl, .grid-stats > .stat-card:nth-child(4) .sub{ color:var(--text) !important; }\\n.grid-stats > .stat-card:nth-child(4) .sub{ color:var(--text-faint) !important; }\\n.grid-stats > .stat-card:nth-child(4) .val{ color:#E3141B !important; }\\n\\n/* Panel & grafik */\\n.panel{ background:#fff; border:1px solid #ECECEF !important; border-radius:16px; box-shadow:var(--shadow); }\\n.panel h3{ color:var(--text); font-weight:700; }\\n.om-chart{ border-bottom:1px dashed #E6E6EA; }\\n.om-bar{ background:linear-gradient(180deg,#F04A50 0%,#E3141B 60%,#B80F15 100%) !important; }\\n.bar-track{ background:#F3F3F5 !important; }\\n.bar-fill{ background:linear-gradient(90deg,#FFB3B5,#E3141B) !important; }\\n.om-table th{ color:var(--text-dim) !important; background:#F7F7F9 !important; }\\n.om-table td{ border-bottom:1px solid #F0F0F2; }\\n.om-table tfoot td{ background:#FFF5F5 !important; }\\n\\n/* Tabel */\\n.table-wrap{ background:#fff; border:1px solid #ECECEF !important; border-radius:16px; }\\nthead th{ background:#F7F7F9 !important; color:var(--text-dim) !important; font-weight:600; border-bottom:1px solid #ECECEF !important; }\\ntbody td{ border-bottom:1px solid #F2F2F4; }\\ntbody tr:hover{ background:#FFF7F7 !important; }\\ntr.model-head td{ background:#FAFAFB !important; }\\n\\n/* Badge */\\n.badge-ready{ background:#E9F8EF !important; color:#15803D !important; border-color:#BFE9CF !important; }\\n.badge-booking{ background:#FFF6E5 !important; color:#B45309 !important; border-color:#FBDDA6 !important; }\\n.badge-sold{ background:#F3F3F5 !important; color:#6B6B76 !important; border-color:#E2E2E7 !important; }\\n.badge-warn{ background:#FDECEC !important; color:#C81016 !important; border-color:#F6C4C6 !important; }\\n\\n/* Input, toggle, filter */\\ninput:focus, select:focus, textarea:focus{ border-color:#F3A3A6 !important; box-shadow:0 0 0 3px rgba(227,20,27,.12) !important; }\\n.field input, .field select, .panel select{ background:#F7F7F9 !important; border-color:#E8E8EC !important; }\\n.view-toggle{ background:#F3F3F5 !important; border-color:#ECECEF !important; box-shadow:none !important; }\\n.view-toggle button.active{ background:#E3141B !important; color:#fff !important; }\\n.price-summary{ background:#FFF5F5 !important; }\\n\\n/* Modal & toast */\\n.overlay{ background:rgba(17,17,20,.45) !important; }\\n.modal{ border-radius:18px; }\\n.toast{ background:#111114 !important; border-color:#111114 !important; color:#fff; }\\n\\n/* Kanban stok */\\n.list{ background:#F7F7F9 !important; backdrop-filter:none !important; -webkit-backdrop-filter:none !important;\\n  border:1px solid #ECECEF !important; border-radius:16px; box-shadow:none !important; }\\n.list.drag-over{ background:#FFF1F1 !important; outline:2px dashed #F3A3A6; }\\n.sticky-actions{ border-color:#ECECEF !important; box-shadow:0 8px 24px rgba(17,17,20,.12) !important; }\\n\\n@media(max-width:760px){ #sidebar{ border-radius:0; } }\\n\\n/* Warna tetap (inline) dari panel tambahan → disesuaikan ke tema merah */\\n#content [style*=\\"#eef4ff\\" i], .modal [style*=\\"#eef4ff\\" i]{ background-color:#FFF5F5 !important; }\\n#content [style*=\\"var(--bg,#f4f6fb)\\"], .modal [style*=\\"var(--bg,#f4f6fb)\\"]{ background:#F7F7F9 !important; }\\n.nmhr-b > div[style*=\\"#60a5fa\\"]{ background:linear-gradient(180deg,#F26A6F 0%,#E3141B 70%,#B80F15 100%) !important; }\\n.nmhr-b > div[style*=\\"color:var(--primary\\"]{ color:#E3141B !important; }\\n#nmHarianPanel div[style*=\\"background:#fff3e0\\"]{ background:linear-gradient(150deg,#F0262D 0%,#E3141B 45%,#A50D12 100%) !important; color:#fff !important;\\n  box-shadow:0 8px 20px rgba(227,20,27,.25); }\\n#nmHarianPanel div[style*=\\"background:#eef4ff\\"]{ background:#F7F7F9 !important; border:1px solid #ECECEF; }\\n#nmHarianPanel div[style*=\\"background:#ecfdf5\\"]{ background:#fff !important; border:1px solid #F6C4C6; }\\n#nmHarianPanel div[style*=\\"background:#ecfdf5\\"] .mono{ color:#E3141B; }"')
VER = CSS.split("\n", 1)[0]
src = open(path, encoding="utf-8").read()
if VER in src: sys.exit(0)
crlf = "\r\n" in src
if crlf: src = src.replace("\r\n", "\n")
blk = '<style id="nm-tema-merah">' + CSS + "</style>\n"
m = re.search(r'<style id="nm-tema-merah">.*?</style>\n?', src, re.S)
if m: src = src[:m.start()] + blk + src[m.end():]
elif "</body>" in src:
    i = src.rfind("</body>"); src = src[:i] + blk + src[i:]
else:
    print("0035: </body> tidak ditemukan - dibatalkan"); sys.exit(2)
if crlf: src = src.replace("\n", "\r\n")
open(path, "w", encoding="utf-8").write(src)
print("0035: tema merah terpasang", VER)
